        mult = solar.multiplier();
    }
    List<ItemStack> credited = SolarMiningMultiplierService.scaleStacks(drops, mult);
    if (mult > 1.0000001d && event.isDropItems()) {
        // Apply solar bank Gold mine boost: cancel vanilla drops, spawn scaled stacks.
        event.setDropItems(false);
        Location dropAt = block.getLocation().add(0.5, 0.5, 0.5);
        for (ItemStack drop : credited) {
            markCredited(drop, source.name());
            block.getWorld().dropItemNaturally(dropAt, drop);
        }
    } else {
        for (ItemStack drop : credited) {
            markCredited(drop, source.name());
        }
    }
    Location loc = block.getLocation();
    recordStacks(player, credited, source, loc, true);
}

